3. Root cause: The repository lacks an Infigraph wrapper. A new module is required to verify the executable's capabilities deterministically, record its version metadata reproducibly for CI verification, and prevent cross-repository graph storage or MCP integration.
4. Proposed implementation:
```python
import dataclasses, json, subprocess
from typing import Literal

STATUS_ANALYSIS_COMPLETE = "analysis_complete"
STATUS_ANALYSIS_UNAVAILABLE = "analysis_unavailable"
STATUS_ANALYSIS_FAILED = "analysis_failed"

@dataclasses.dataclass(frozen=True, slots=True)
class CapabilityReport:
    status: Literal["analysis_complete", "analysis_unavailable", "analysis_failed"]
    version: str | None = None
    capabilities: tuple[str, ...] = ()
    reason: str | None = None

def check_capabilities(executable: str = "infigraph", timeout: int = 15) -> CapabilityReport:
    try:
        result = subprocess.run([executable, "capabilities", "--format=json"], capture_output=True, text=True, timeout=timeout, check=False)
    except FileNotFoundError:
        return CapabilityReport(status=STATUS_ANALYSIS_UNAVAILABLE, reason="executable not found")
    except subprocess.TimeoutExpired:
        return CapabilityReport(status=STATUS_ANALYSIS_FAILED, reason="command timed out")
    except Exception as e:
        return CapabilityReport(status=STATUS_ANALYSIS_FAILED, reason=f"execution error: {e}")

    if result.returncode != 0:
        return CapabilityReport(status=STATUS_ANALYSIS_FAILED, reason=f"command failed with code {result.returncode}")

    try:
        data = json.loads(result.stdout)
        return CapabilityReport(status=STATUS_ANALYSIS_COMPLETE, version=data.get("version"), capabilities=tuple(data.get("capabilities", [])))
    except json.JSONDecodeError:
        return CapabilityReport(status=STATUS_ANALYSIS_FAILED, reason="malformed output")

def record_resolution_metadata(executable: str = "infigraph", output_file: str = "infigraph_resolution.json", timeout: int = 15) -> bool:
    report = check_capabilities(executable=executable, timeout=timeout)
    if report.status != STATUS_ANALYSIS_COMPLETE:
        return False
    metadata = {"executable": executable, "version": report.version, "capabilities": report.capabilities, "resolved_at_status": "pinned"}
    try:
        with open(output_file, "w") as f:
            json.dump(metadata, f, indent=2)
        return True
    except IOError:
        return False

def invoke_analysis(target_path: str, executable: str = "infigraph", timeout: int = 30) -> dict[str, str]:
    if ".." in target_path or target_path.startswith("/") or "mcp" in target_path.lower():
        return {"status": STATUS_ANALYSIS_FAILED, "reason": "invalid target path"}

    try:
        result = subprocess.run([executable, "analyze", target_path, "--format=json"], capture_output=True, text=True, timeout=timeout, check=False)
    except FileNotFoundError:
        return {"status": STATUS_ANALYSIS_UNAVAILABLE, "reason": "executable not found"}
    except subprocess.TimeoutExpired:
        return {"status": STATUS_ANALYSIS_FAILED, "reason": "command timed out"}

    if result.returncode != 0:
        return {"status": STATUS_ANALYSIS_FAILED, "reason": f"command failed: {result.stderr.strip()}"}

    return {"status": STATUS_ANALYSIS_COMPLETE, "output": result.stdout.strip()}
```
5. Integration points: `scripts/kb/infigraph_runtime.py` provides standalone deterministic functions. No existing files are modified.
6. Test scenarios: Mock `subprocess.run` to cover successful capability discovery (valid JSON returned), command timeout (raises `subprocess.TimeoutExpired`), missing executable (raises `FileNotFoundError`), and malformed JSON output. Also test `invoke_analysis` boundary conditions (`..`, `/`, `mcp`) and `record_resolution_metadata` success.
7. Acceptance Criteria: The wrapper must define normalized statuses for analysis_complete, analysis_unavailable, and analysis_failed. It must record release and resolution metadata reproducibly for CI. Tests must cover successful capability discovery and representative installation/capability/command failures. Ensure no cross-repository graph storage or MCP integration is introduced.
